package main

import "fmt"

func main() {
    text := "a界b"
    fmt.Println("bytes", len(text))
    for index, value := range text {
        fmt.Printf("%d:%c ", index, value)
    }
    fmt.Println()
}
```
The indexes are 0, 1, and 4. They locate rune starts in the original five-byte string.

```go
package main

import "fmt"

func main() {
    text := "a界bc"
    position := 0
    for offset, value := range text {
        if value == 'b' {
            fmt.Println("rune position", position)
            fmt.Println("byte offset", offset)
            fmt.Println("suffix", text[offset:])
        }
        position++
    }
}
```
For `b`, the rune position is 2 and the byte offset is 4. The offset safely slices the original string into suffix `bc`.

```go
package main

import "fmt"

func reverseRunes(text string) string {
    values := []rune(text)
    for left, right := 0, len(values)-1; left < right; left, right = left+1, right-1 {
        values[left], values[right] = values[right], values[left]
    }
    return string(values)
}

func main() {
    fmt.Println(reverseRunes("Go界"))
}
```
The output is `界oG`. Each UTF-8 code point remains correctly encoded after the reversal.
